package ru.neverland.mintcontracts.service;

import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.*;
import ru.neverland.mintcontracts.integration.TownyHook;
import ru.neverland.mintcontracts.model.*;

/** Uses the existing funded municipal-contract escrow and delivery receipts. No server emission. */
public final class BuildOrders implements CommandExecutor,Listener {
    private final JavaPlugin plugin;private final TownyHook towns;private final ContractService contracts;
    public BuildOrders(JavaPlugin plugin,TownyHook towns,ContractService contracts){this.plugin=plugin;this.towns=towns;this.contracts=contracts;plugin.getServer().getPluginManager().registerEvents(this,plugin);towns.register("buildorders",this);plugin.getCommand("townybuildorders").setExecutor(this);}
    public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p))return true;SuiteScheduler.player(plugin,p,ignored->{try(var g=SuiteState.guard()){try{Town town=authorize(p);if(args.length!=1)throw new IllegalArgumentException("Откройте нужное здание и нажмите «Заказать материалы горожанам»");open(p,town,args[0]);}catch(Exception ex){p.sendMessage("§e"+reason(ex));}}});return true;}
    private Town authorize(Player p){Town t=towns.town(p);if(!plugin.getConfig().getBoolean("building-orders.enabled",true)||SuiteState.frozen(plugin.getName()))throw new IllegalArgumentException("Заказы на материалы сейчас приостановлены");if(t==null||!t.isMayor(towns.resident(p))||!p.hasPermission("mintcontracts.buildorders"))throw new IllegalArgumentException("Публиковать заказы на материалы может мэр города");return t;}
    @SuppressWarnings("unchecked") private Map<String,Object> needs(UUID town,String project)throws Exception{return(Map<String,Object>)ApiServices.require("NeverLandTownyBuilds","ru.neverland.townybuilds.api.BuildingMaterialsApi","needs").invoke("needs",new Class<?>[]{UUID.class,String.class},town,project);}
    private record Quote(String project,String fingerprint,int level,String title,ContractDefinition definition){}
    private Quote quote(Map<String,Object> needs,Map<?,?> item){
        String encoded=(String)item.get("item"),project=(String)needs.get("project");int amount=((Number)item.get("amount")).intValue(),level=((Number)needs.get("targetLevel")).intValue();ItemStack sample=ContractCodec.item(encoded);
        String raw=plugin.getConfig().getString("building-orders.unit-rewards."+sample.getType().name(),plugin.getConfig().getString("building-orders.default-unit-reward","0.10"));
        long unit=money(raw),maximum=money(plugin.getConfig().getString("building-orders.maximum-reward","50000.00"));long cents=Math.multiplyExact(unit,amount);if(cents<1||cents>maximum)throw new IllegalArgumentException("Награда за эту поставку превышает настройки города. Обратитесь к администратору");
        long seconds=plugin.getConfig().getLong("building-orders.duration-seconds",86400);String key=UUID.nameUUIDFromBytes(encoded.getBytes(StandardCharsets.UTF_8)).toString().replace("-","").substring(0,16);String id="build_"+project+"_"+level+"_"+key;
        var d=new ContractDefinition(id,"&f"+item.get("name")+" для стройки",ContractType.DELIVERY,sample.getType(),0,List.of("&7Здание: "+needs.get("title")+" • уровень "+level,"&7Оплачено из городской казны","&7Ресурсы поступают на склад города"),sample.getType().name(),sample,amount,cents/100.0,seconds);
        return new Quote(project,(String)needs.get("fingerprint"),level,String.valueOf(needs.get("title")),d);
    }
    public static long money(String value){try{long n=new BigDecimal(value).movePointRight(2).longValueExact();if(n<=0||n>100_000_000_000L)throw new IllegalArgumentException();return n;}catch(Exception ex){throw new IllegalArgumentException("Неверная ставка или предел награды в настройках заказов на стройку");}}
    private void open(Player p,Town t,String project)throws Exception{var n=needs(t.getUUID(),project);var v=new View(p.getUniqueId(),t.getUUID(),project,null);v.inventory=MenuStyle.inventory(plugin,v,54,"Материалы для здания");int slot=0;for(Object raw:(List<?>)n.get("materials")){Quote q=quote(n,(Map<?,?>)raw);if(slot>=45)break;v.quotes.put(slot,q);v.inventory.setItem(slot++,icon(q.definition().icon(),q.definition().name(),List.of("Здание: "+q.title()+" • ур. "+q.level(),"Нужно принести: "+q.definition().goal(),"Общая награда: "+format(q.definition().reward())+" монет","Оплата из казны города","Нажмите, чтобы проверить и подтвердить")));}if(slot==0)v.inventory.setItem(22,icon(Material.LIME_DYE,"Материалы уже собраны",List.of("Используйте склад и взносы в здание")));v.inventory.setItem(49,icon(Material.ARROW,"Назад к зданию",List.of()));p.openInventory(v.inventory);}
    private void confirm(Player p,Town t,Quote q){var v=new View(p.getUniqueId(),t.getUUID(),q.project(),q);v.inventory=MenuStyle.inventory(plugin,v,27,"Подтвердить городской заказ");v.inventory.setItem(11,icon(Material.LIME_DYE,"Оплатить и опубликовать",List.of(q.definition().goal()+" шт. • "+net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(MenuStyle.decode(q.definition().name())),"Из казны: "+format(q.definition().reward())+" монет","Срок: "+q.definition().durationSeconds()/3600+" ч.","Ресурсы придут на склад города","После публикации: /t contracts")));v.inventory.setItem(15,icon(Material.ARROW,"Назад",List.of()));p.openInventory(v.inventory);}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!v.owner.equals(p.getUniqueId())||e.getRawSlot()<0||e.getRawSlot()>=v.inventory.getSize())return;int slot=e.getRawSlot();SuiteScheduler.player(plugin,p,ignored->{try(var g=SuiteState.guard()){try{if(v.used||System.currentTimeMillis()>v.expires)throw new IllegalArgumentException("Условия устарели. Откройте здание ещё раз");Town t=authorize(p);if(!t.getUUID().equals(v.town))throw new IllegalArgumentException("Город изменился");if(v.selected==null){if(slot==49){v.used=true;p.performCommand("town builds "+v.project);return;}Quote q=v.quotes.get(slot);if(q!=null){v.used=true;confirm(p,t,q);}return;}if(slot==15){v.used=true;open(p,t,v.project);return;}if(slot!=11)return;v.used=true;Map<String,Object> n=needs(t.getUUID(),v.project);if(!v.selected.fingerprint().equals(n.get("fingerprint")))throw new IllegalArgumentException("Количество материалов изменилось. Проверьте заказ заново");Quote current=null;for(Object raw:(List<?>)n.get("materials")){Quote q=quote(n,(Map<?,?>)raw);if(q.definition().id().equals(v.selected.definition().id()))current=q;}if(current==null||current.definition().reward()!=v.selected.definition().reward())throw new IllegalArgumentException("Условия изменились. Проверьте заказ заново");var result=contracts.activate(t,current.definition());p.closeInventory();p.sendMessage("§e"+switch(result){case SUCCESS->"Заказ оплачен из казны и опубликован: /t contracts";case DUPLICATE->"Такой заказ уже опубликован";case MAX_ACTIVE->"Сначала завершите один из действующих заказов города";case NO_MONEY->"В казне не хватает денег на награду";case ECONOMY_ERROR->"Оплата ожидает сверки. Не публикуйте заказ повторно";case WAREHOUSE_UNAVAILABLE->"Склад города сейчас недоступен";case SAVE_ERROR->"Заказ не опубликован: не удалось сохранить данные";});}catch(Exception ex){p.sendMessage("§e"+reason(ex));}}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
    private static String format(double amount){return BigDecimal.valueOf(amount).setScale(2).toPlainString();}
    private static String reason(Exception ex){Throwable t=ex;while(t.getCause()!=null)t=t.getCause();return t.getMessage()==null?"Заказы на материалы сейчас недоступны":t.getMessage();}
    private static ItemStack icon(Material material,String name,List<String> lore){var i=new ItemStack(material);var m=i.getItemMeta();m.displayName(MenuStyle.nameComponent(MenuStyle.decode(name)));m.lore(MenuStyle.loreComponents(lore.stream().map(MenuStyle::decode).toList()));m.addItemFlags(ItemFlag.values());i.setItemMeta(m);return i;}
    private static final class View implements InventoryHolder{final UUID owner,town;final String project;final Quote selected;final long expires=System.currentTimeMillis()+30_000;boolean used;Inventory inventory;final Map<Integer,Quote> quotes=new HashMap<>();View(UUID owner,UUID town,String project,Quote selected){this.owner=owner;this.town=town;this.project=project;this.selected=selected;}public Inventory getInventory(){return inventory;}}
}
